// Generated by tools/emit_sa8d_sve2_shared.py -- do not edit by hand.
// SA8D 16x16 (VL=256): each 16-pixel row is one natural 16-lane register,
// so unlike the 8x8 pack variants there is NO row-packing (SEL), no high-half
// extraction, no TBL2 re-pack, and no half-rotation max. Every stage runs
// lane-wise across the 16 row registers and processes the left/right 8x8
// quadrants simultaneously, i.e. the 128-bit upstream instruction count
// (373 fused) is truly halved (~180).
#include <arm_sve.h>

static const uint16_t HAD_IDX16[16] =
    { 0, 2, 4, 6, 1, 3, 5, 7, 8, 10, 12, 14, 9, 11, 13, 15 };

extern "C" int dynopt_sa8d_16x16_sve2(const uint8_t* pix1, intptr_t sp1,
                       const uint8_t* pix2, intptr_t sp2)
{
    const svbool_t p16 = svptrue_b16();
    const svuint16_t had_idx = svld1_u16(p16, HAD_IDX16);

    #define LD(r) svreinterpret_s16_u16(svsub_u16_x(                     \
        p16,                                                              \
        svld1ub_u16(p16, pix1 + (r) * sp1),                               \
        svld1ub_u16(p16, pix2 + (r) * sp2)))
    #define ROWH(p)                                                       \
        p = svcadd_s16(p, p, 90);                                         \
        p = svtbl_s16(p, had_idx);                                        \
        p = svcadd_s16(p, p, 90);                                         \
        p = svtbl_s16(p, had_idx);                                        \
        p = svcadd_s16(p, p, 90);                                         \
        (void)0
    #define SUMSUB(s, u, a, b) do {                                       \
        s = svadd_s16_x(p16, a, b);                                       \
        u = svsub_s16_x(p16, a, b);                                       \
    } while (0)
    #define ABSSUB(s, u, a, b) do {                                       \
        s = svabs_s16_x(p16, svadd_s16_x(p16, a, b));                     \
        u = svabd_s16_x(p16, a, b);                                       \
    } while (0)

    svint16_t r0 = LD(0);  ROWH(r0);
    svint16_t r1 = LD(1);  ROWH(r1);
    svint16_t r2 = LD(2);  ROWH(r2);
    svint16_t r3 = LD(3);  ROWH(r3);
    svint16_t r4 = LD(4);  ROWH(r4);
    svint16_t r5 = LD(5);  ROWH(r5);
    svint16_t r6 = LD(6);  ROWH(r6);
    svint16_t r7 = LD(7);  ROWH(r7);
    svint16_t r8 = LD(8);  ROWH(r8);
    svint16_t r9 = LD(9);  ROWH(r9);
    svint16_t r10 = LD(10); ROWH(r10);
    svint16_t r11 = LD(11); ROWH(r11);
    svint16_t r12 = LD(12); ROWH(r12);
    svint16_t r13 = LD(13); ROWH(r13);
    svint16_t r14 = LD(14); ROWH(r14);
    svint16_t r15 = LD(15); ROWH(r15);

    // Column H level 1 (both quadrants per instruction).
    svint16_t s0, s1, s2, s3, s4, s5, s6, s7;
    svint16_t s8, s9, s10, s11, s12, s13, s14, s15;
    SUMSUB(s0, s1, r0, r1);
    SUMSUB(s2, s3, r2, r3);
    SUMSUB(s4, s5, r4, r5);
    SUMSUB(s6, s7, r6, r7);
    SUMSUB(s8, s9, r8, r9);
    SUMSUB(s10, s11, r10, r11);
    SUMSUB(s12, s13, r12, r13);
    SUMSUB(s14, s15, r14, r15);

    // Column H levels 2+3 with abs (upstream pairing).
    svint16_t a0, a1, a2, a3, a4, a5, a6, a7;
    svint16_t a8, a9, a10, a11, a12, a13, a14, a15;
    ABSSUB(a0, a2, s0, s2);
    ABSSUB(a1, a3, s1, s3);
    ABSSUB(a4, a6, s4, s6);
    ABSSUB(a5, a7, s5, s7);
    ABSSUB(a8, a10, s8, s10);
    ABSSUB(a9, a11, s9, s11);
    ABSSUB(a12, a14, s12, s14);
    ABSSUB(a13, a15, s13, s15);

    // SATD max/accumulate: |x+y|+|x-y| = 2*max(|x|,|y|), so sum the
    // per-lane maxima instead of the abs values themselves.
    svint16_t m0 = svmax_s16_x(p16, a0, a4);
    svint16_t m1 = svmax_s16_x(p16, a1, a5);
    svint16_t m2 = svmax_s16_x(p16, a2, a6);
    svint16_t m3 = svmax_s16_x(p16, a3, a7);
    svint16_t m4 = svmax_s16_x(p16, a8, a12);
    svint16_t m5 = svmax_s16_x(p16, a9, a13);
    svint16_t m6 = svmax_s16_x(p16, a10, a14);
    svint16_t m7 = svmax_s16_x(p16, a11, a15);

    svint16_t t0 = svadd_s16_x(p16, m0, m1);
    svint16_t t1 = svadd_s16_x(p16, m2, m3);
    svint16_t t2 = svadd_s16_x(p16, m4, m5);
    svint16_t t3 = svadd_s16_x(p16, m6, m7);
    svint16_t s = svadd_s16_x(p16, svadd_s16_x(p16, t0, t1),
                              svadd_s16_x(p16, t2, t3));

    svuint64_t dot = svdot_u64(svdup_n_u64(0),
                               svreinterpret_u16_s16(s), svdup_n_u16(1));
    uint64_t total = svaddv_u64(svptrue_b64(), dot);
    return (int)((total + 1) >> 1);
}
